INSERT INTO `notices` VALUES ('今日22:00停水通知', '因管道维修，今晚22:00至次日6:00全小区停水，请提前储水。', '物业办公室', 3, '2026-05-15 22:34:24');
INSERT INTO `notices` VALUES ('谨防电信诈骗宣传', '近期诈骗频发，请勿轻信陌生来电，涉及转账请务必核实身份。', '辖区派出所', 2, '2026-06-15 22:35:52');
INSERT INTO `notices` VALUES ('社区义诊活动', '本周六上午9点，在这个广场举办义诊，欢迎老年朋友参加。', '居委会', 1, '2026-04-15 22:36:15');
INSERT INTO `notices` VALUES ('燃气检修通知', '因燃气公司例行安全检修，明日8:00至18:00全小区暂停供应燃气，请居民注意用火安全，避免使用燃气设备。', '物业办公室', 3, '2026-08-20 09:15:47');
INSERT INTO `notices` VALUES ('电梯维保通知', '因电梯定期保养维护，明天上午9:00至12:00 1号电梯将暂停使用，请居民尽量走楼梯或使用2号电梯，给您带来不便敬请谅解。', '物业办公室', 2, '2026-04-16 22:51:23');
INSERT INTO `notices` VALUES ('临时道路管制通知', '因市政道路施工，2026年5月15日8:00至18:00小区东门主干道临时封闭，请车辆绕行西门，给您出行带来不便敬请谅解。', '辖区派出所', 2, '2026-05-13 09:42:11');
INSERT INTO `notices` VALUES ('垃圾分类督导通知', '从5月25日起，居委会将联合城管开展垃圾分类入户督导，请居民配合投放厨余垃圾和其他垃圾，共同创建文明小区。', '居委会', 1, '2026-05-20 13:21:48');
INSERT INTO `notices` VALUES ('测试', 'aaa', 'yejisu', 3, '2026-01-11 20:11:55');

