INSERT INTO `troubles` VALUES (4, '卫生间进水管突然爆裂，水流非常大，请尽快派人来修！家里快淹了！', '1766467436_9383.jpg;/uploads/1766467436_886.jpg;/uploads/1766467436_2777.jpg', '2025-12-23 13:23:55', 5, 1, 2, 'yejisu');
INSERT INTO `troubles` VALUES (5, '6楼过道有邻居堆放大量纸箱，影响通行，且存在消防隐患，请物业协调处理。', '1766467581_9383.jpg', '2025-12-23 13:26:19', 3, 2, 2, 'yejisu');
INSERT INTO `troubles` VALUES (6, '3单元4楼的感应灯不亮了，老人上下楼不方便。', '1766467613_886.jpg;/uploads/1766467613_2777.jpg', '2025-12-23 13:26:51', 4, 1, 1, 'yejisu');
INSERT INTO `troubles` VALUES (7, '最近每到半夜两点，楼上总是有拖拽重物的声音，已经持续一周了，严重影响睡眠质量，希望物业能查一下是哪一家，或者在群里通知一下...', NULL, '2025-12-23 15:19:04', 5, 2, 2, 'yeji');
INSERT INTO `troubles` VALUES (8, '公园长椅的一条腿断了。', NULL, '2025-12-23 15:19:43', 2, 1, 1, 'yeji');
INSERT INTO `troubles` VALUES (9, '卫生间水管漏了，速速来修', '', '2025-12-23 15:41:19', 5, 1, 2, 'yeji');
INSERT INTO `troubles` VALUES (27, 'ITZYyyds', '1767861355_9383.jpg;1767861355_886.jpg;1767861355_2777.jpg;1767861355_6915.jpg;1767861355_7793.jpg', '2026-01-08 16:35:54', 5, 1, 1, 'chaeryeong');
INSERT INTO `troubles` VALUES (39, '测试', '1768133481_9383.jpg;1768133481_886.jpg;1768133481_2777.jpg', '2026-01-11 20:11:23', 4, 1, 2, 'yejisu');

-- ----------------------------
-- Table structure for user_info
-- ----------------------------
DROP TABLE IF EXISTS `user_info`;
CREATE TABLE `user_info`  (
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '登录账号',
  `password` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '登录密码',
  `realname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '真实姓名',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `avatar` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '保存头像',
  `sex` tinyint(1) NULL DEFAULT NULL COMMENT '性别',
  `building` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '楼栋',
  `floor` tinyint NULL DEFAULT NULL COMMENT '楼层',
  `housenum` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `balance` double NULL DEFAULT NULL COMMENT '余额',
  UNIQUE INDEX `uk_username`(`username` ASC) USING BTREE COMMENT '账号必须唯一'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户信息表' ROW_FORMAT = Dynamic;

